node -e 'const fs=require("fs"),path=require("path")
const fail=(m)=>{console.error("LIVE-707 FAILED: "+m);process.exit(1)}
const P="app/space-email-policy/page.tsx"
if(!fs.existsSync(P))fail("there is no Space email acceptable-use draft for counsel to review at app/space-email-policy/page.tsx")
const norm=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")
const body=norm(fs.readFileSync(P,"utf8"))
if(!/robots:\s*\{\s*index:\s*false/.test(body))fail("the draft does not ask to stay out of search, so it can pass for live policy")
if(!body.includes("DRAFT. Not in force, and no lawyer has read it yet."))fail("the draft no longer opens by saying it is an unreviewed draft")
if(!body.includes("For counsel: open questions."))fail("the draft has lost its open questions for counsel")
if(/[–—]/.test(body))fail("the draft carries an em or en dash (CONTENT-VOICE)")
if(fs.readFileSync("app/sitemap.ts","utf8").includes("space-email-policy"))fail("the sitemap advertises the draft as a public page")
const walk=(d,o)=>{for(const n of fs.readdirSync(d)){if(n==="node_modules"||n.startsWith("."))continue;const p=path.join(d,n);if(fs.statSync(p).isDirectory())walk(p,o);else if(/\.(tsx?|mjs|txt)$/.test(n)&&!/\.test\.tsx?$/.test(n))o.push(p)}return o}
const linkers=["app","components","lib"].flatMap((d)=>walk(d,[])).filter((p)=>!p.startsWith("app/space-email-policy")).filter((p)=>norm(fs.readFileSync(p,"utf8")).includes("/space-email-policy"))
if(linkers.length)fail("the draft is linked as if it were final from: "+linkers.join(", "))
const cap=/export const DAILY_SEND_CAP = ([\d_]+)/.exec(fs.readFileSync("lib/spaces/email.ts","utf8"))
if(!cap)process.exit(79)
const n=Number(cap[1].replace(/_/g,"")).toLocaleString("en-US")
if(!body.includes("up to "+n+" emails a day"))fail("the draft states a daily limit the send backbone does not enforce (the code says "+n+")")
console.log("ok")'
